    pub(in crate::mcp) fn get_compile_status(&self) -> ToolResult {
        ok(self.session().compile_status())
    }

    #[tool(
        description = "Frame a certified captured world position from the latest finished build job. Pass job_token from compile_map or get_compile_status.job.token and the stable diagnostic index from its first 100 retained rows. Inspect frame_available and frame_unavailable_reason first; position_space must be world. Optional finite aspect defaults to 1 (0.01–100). Frames the recorded historical position without claiming current source identity. Wrong or replaced tokens, invalid indices, unclassified or invalid positions and viewport conflicts reject while preserving the camera. Preserves selection, history and ordinary drafts. UI: Build details → Frame recorded position."
    )]
    pub(in crate::mcp) fn frame_build_diagnostic(
        &self,
        Parameters(args): Parameters<FrameBuildDiagnosticArgs>,
    ) -> ToolResult {
        run(|| {
            self.session().frame_build_diagnostic(
                Actor::Agent,
                &args.job_token,
                args.index,
                args.aspect.unwrap_or(1.0),
            )
        })
    }

    #[tool(
        description = "Request cancellation of the exact queued or running compile job. Queued work retires promptly; running work remains busy until its owned cleanup stops. Poll get_compile_status until cancelled. Cancellation is rejected once output publication has completed. Previous BSP and pointfile remain unchanged when cancellation is accepted."
    )]
    pub(in crate::mcp) fn cancel_compile(
        &self,
        Parameters(args): Parameters<CompileTokenArgs>,
    ) -> ToolResult {
        run(|| {
            let token = args
                .token
                .parse()
                .map_err(|_| "Invalid compile job token")?;
            self.document_access().cancel_compile(Actor::Agent, token)
        })
    }

